  sv_records: ['Public records (FOIA) request', 'Solicitud de registros públicos (FOIA)'],
  sv_county_h: ['Building permits come from the county.', 'Los permisos de construcción los da el condado.'],
  sv_county_p: ['The town checks where you can build (zoning). Charlotte County checks how (building code). Start with the town form and the clerk will tell you if you need both.', 'El pueblo revisa dónde puede construir (zonificación). El condado de Charlotte revisa cómo (código de construcción). Empiece con el formulario del pueblo y la secretaría le dirá si necesita ambos.'],
  sv_emerg_h: ['Is it an emergency?', '¿Es una emergencia?'],
  sv_emerg_p: ['For a water main break, sewage backup or anything dangerous, don’t use this form. Call the after-hours line at [after-hours number] or 911.', 'Si hay una rotura de tubería principal, un desborde de aguas negras o algo peligroso, no use este formulario. Llame a la línea fuera de horario al [número fuera de horario] o al 911.'],
  sv_what: ['What is the problem?', '¿Cuál es el problema?'],
