  sv_cat_light: ['Streetlight out', 'Farol apagado'],
  sv_cat_leak: ['Water leak or low pressure', 'Fuga de agua o baja presión'],
  sv_cat_trash: ['Missed trash pickup', 'No recogieron la basura'],
  sv_cat_billing: ['Water bill question', 'Pregunta sobre la factura de agua'],
