  sv_route_pick: ['Pick a category and we’ll show you who handles it.', 'Elija una categoría y le mostramos quién la atiende.'],
  sv_route_to: ['This goes to: {dept}.', 'Esto va a: {dept}.'],
  sv_route_vdot: ['If the street is a state route, it may go to VDOT; the town files it for you either way.', 'Si la calle es una ruta estatal, puede ir a VDOT; de cualquier forma el pueblo lo reporta por usted.'],
  sv_route_light: ['The light belongs to the electric company; Public Works files the repair for you.', 'El farol pertenece a la compañía eléctrica; Obras Públicas hace el reporte por usted.'],
  sv_also_oncall: ['A text also goes to the on-call phone.', 'También se envía un texto al teléfono de guardia.'],
