  rc_estimate: ['Give me a cost estimate before you start. Don’t do any work until I agree to the cost.', 'Denme un estimado de costo antes de empezar. No hagan ningún trabajo hasta que yo acepte el costo.'],
  rc_estimate_short: ['estimate first', 'estimado primero'],
