  rc_err_contact: ['Give a phone number or an email address.', 'Indique un teléfono o un correo electrónico.'],
  rc_done_title: ['Your records request is in', 'Su solicitud de registros fue recibida'],
  rc_done_1: ['The FOIA officer must respond by {date}. That’s five working days, not counting weekends or town holidays.', 'El oficial de FOIA debe responder antes del {date}. Son cinco días hábiles, sin contar fines de semana ni feriados del pueblo.'],
  rc_done_2: ['If you asked for an estimate, you’ll get the cost first and nothing happens until you say yes.', 'Si pidió un estimado, recibirá el costo primero y nada avanza hasta que usted acepte.'],
  rc_done_3: ['If we need more time, we tell you in writing and take up to seven more working days.', 'Si necesitamos más tiempo, se lo decimos por escrito y tomamos hasta siete días hábiles más.'],
